import express, {
  type ErrorRequestHandler,
  type Express,
  type Request,
  type Response,
} from "express";
import type { CatalogueService } from "../application/catalogue-service";
import type { OrderService, PlaceOrderCommand } from "../application/order-service";
import {
  DomainError,
  InsufficientStockError,
  InvalidTransitionError,
  NotFoundError,
  ValidationError,
} from "../domain/errors";
import { isOrderState, ORDER_STATES } from "../domain/order";

export interface Services {
  catalogue: CatalogueService;
  orders: OrderService;
}

export function createApp({ catalogue, orders }: Services): Express {
  const app = express();
  app.use(express.json());

  app.get("/health", (_req, res) => {
    res.json({ status: "ok" });
  });

  // --- Catalogue & stock -------------------------------------------------

  app.get("/products", (_req, res) => {
    res.json(catalogue.listProducts());
  });

  app.post("/products", (req, res) => {
    const body = asObject(req.body);
    const product = catalogue.addProduct({
      id: requireString(body, "id"),
      name: requireString(body, "name"),
      priceCents: requireNumber(body, "priceCents"),
      initialStock: requireNumber(body, "initialStock"),
    });
    res.status(201).json(product);
  });

  app.get("/products/:id", (req, res) => {
    res.json(catalogue.getProduct(param(req, "id")));
  });

  app.post("/products/:id/restock", (req, res) => {
    const body = asObject(req.body);
    res.json(catalogue.restock(param(req, "id"), requireNumber(body, "quantity")));
  });

  /** Staff view: stock level of every product. */
  app.get("/stock", (_req, res) => {
    res.json(
      catalogue.listProducts().map(({ id, name, stockOnHand, reserved, available }) => ({
        productId: id,
        name,
        stockOnHand,
        reserved,
        available,
      })),
    );
  });

  // --- Orders ------------------------------------------------------------

  app.post("/orders", (req, res) => {
    const body = asObject(req.body);
    const rawItems = body["items"];
    if (!Array.isArray(rawItems)) {
      throw new ValidationError("items must be an array");
    }
    const command: PlaceOrderCommand = {
      customerId: requireString(body, "customerId"),
      items: rawItems.map((raw: unknown) => {
        const item = asObject(raw);
        return {
          productId: requireString(item, "productId"),
          quantity: requireNumber(item, "quantity"),
        };
      }),
    };
    res.status(201).json(orders.placeOrder(command));
  });

  /** Staff view: list orders, optionally filtered by `?state=`. */
  app.get("/orders", (req, res) => {
    const state = req.query["state"];
    if (state === undefined) {
      res.json(orders.listOrders());
      return;
    }
    if (!isOrderState(state)) {
      throw new ValidationError(`state must be one of: ${ORDER_STATES.join(", ")}`);
    }
    res.json(orders.listOrders(state));
  });

  app.get("/orders/:id", (req, res) => {
    res.json(orders.getOrder(param(req, "id")));
  });

  /** Explicit transition: body `{ "state": "paid" }`. */
  app.post("/orders/:id/transitions", (req, res) => {
    const body = asObject(req.body);
    const state = body["state"];
    if (!isOrderState(state)) {
      throw new ValidationError(`state must be one of: ${ORDER_STATES.join(", ")}`);
    }
    res.json(orders.transition(param(req, "id"), state));
  });

  app.post("/orders/:id/pay", (req, res) => {
    res.json(orders.transition(param(req, "id"), "paid"));
  });
  app.post("/orders/:id/pack", (req, res) => {
    res.json(orders.transition(param(req, "id"), "packed"));
  });
  app.post("/orders/:id/ship", (req, res) => {
    res.json(orders.transition(param(req, "id"), "shipped"));
  });
  app.post("/orders/:id/deliver", (req, res) => {
    res.json(orders.transition(param(req, "id"), "delivered"));
  });
  app.post("/orders/:id/advance", (req, res) => {
    res.json(orders.advance(param(req, "id")));
  });
  app.post("/orders/:id/cancel", (req, res) => {
    res.json(orders.cancel(param(req, "id")));
  });

  app.use((_req: Request, res: Response) => {
    res.status(404).json({ error: { code: "NOT_FOUND", message: "Route not found" } });
  });

  app.use(errorHandler);
  return app;
}

const errorHandler: ErrorRequestHandler = (err: unknown, _req, res, _next) => {
  if (err instanceof DomainError) {
    const body: Record<string, unknown> = { code: err.code, message: err.message };
    if (err instanceof InsufficientStockError) {
      body["productId"] = err.productId;
      body["requested"] = err.requested;
      body["available"] = err.available;
    }
    res.status(statusFor(err)).json({ error: body });
    return;
  }
  if (isBodyParseError(err)) {
    res.status(400).json({ error: { code: "VALIDATION_ERROR", message: "Malformed JSON body" } });
    return;
  }
  console.error(err);
  res.status(500).json({ error: { code: "INTERNAL_ERROR", message: "Internal server error" } });
};

function statusFor(err: DomainError): number {
  if (err instanceof ValidationError) return 400;
  if (err instanceof NotFoundError) return 404;
  if (err instanceof InsufficientStockError) return 409;
  if (err instanceof InvalidTransitionError) return 409;
  return 400;
}

function isBodyParseError(err: unknown): boolean {
  return (
    typeof err === "object" &&
    err !== null &&
    (err as { type?: unknown }).type === "entity.parse.failed"
  );
}

// --- Request parsing helpers ----------------------------------------------

function param(req: Request, name: string): string {
  const value: unknown = req.params[name];
  if (typeof value !== "string" || value === "") {
    throw new ValidationError(`Missing path parameter ${name}`);
  }
  return value;
}

function asObject(value: unknown): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new ValidationError("Expected a JSON object");
  }
  return value as Record<string, unknown>;
}

function requireString(body: Record<string, unknown>, field: string): string {
  const value = body[field];
  if (typeof value !== "string" || value.trim() === "") {
    throw new ValidationError(`${field} must be a non-empty string`);
  }
  return value;
}

function requireNumber(body: Record<string, unknown>, field: string): number {
  const value = body[field];
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new ValidationError(`${field} must be a number`);
  }
  return value;
}

